from collections import deque

def longest_increasing_path(matrix):
    m, n = len(matrix), len(matrix[0])
    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))
    out = [[0] * n for _ in range(m)]  # how many neighbours are larger
    for r in range(m):
        for c in range(n):
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] > matrix[r][c]:
                    out[r][c] += 1
    layer = deque((r, c) for r in range(m) for c in range(n) if out[r][c] == 0)
    depth = 0
    while layer:                       # peel local maxima, one layer at a time
        depth += 1
        for _ in range(len(layer)):
            r, c = layer.popleft()
            for dr, dc in dirs:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and matrix[nr][nc] < matrix[r][c]:
                    out[nr][nc] -= 1
                    if out[nr][nc] == 0:
                        layer.append((nr, nc))
    return depth

