def min_path_sum(grid):
    n = len(grid[0])
    row = [0] + [float('inf')] * (n - 1)
    for cells in grid:
        row[0] += cells[0]
        for j in range(1, n):
            row[j] = cells[j] + min(row[j], row[j - 1])   # from above or left
    return row[-1]

