def unique_paths(m, n):
    dp = [[1] * n for _ in range(m)]   # first row and column: one way each
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
    return dp[-1][-1]

