def unique_paths_with_obstacles(grid):
    n = len(grid[0])
    row = [1] + [0] * (n - 1)
    for cells in grid:
        for j in range(n):
            if cells[j] == 1:
                row[j] = 0             # obstacle: no paths through here
            elif j > 0:
                row[j] += row[j - 1]
    return row[-1]

